package com.lexorion.workforce.repository;import com.lexorion.workforce.domain.*;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface DepartmentRepository extends JpaRepository<Department,UUID>{@Query("select d from Department d left join fetch d.parent where d.workspace.id=:workspaceId order by d.name")List<Department> findByWorkspaceIdOrderByNameAsc(@Param("workspaceId")UUID workspaceId);Optional<Department> findByWorkspaceIdAndKey(UUID workspaceId,String key);boolean existsByWorkspaceIdAndKey(UUID workspaceId,String key);}
